python3 -c "
import gspread
from google.oauth2.service_account import Credentials
from datetime import datetime
from collections import defaultdict

scopes = ['https://www.googleapis.com/auth/spreadsheets.readonly']
creds = Credentials.from_service_account_file('./wuhu-generals-ranking/service-account.json', scopes=scopes)
gc = gspread.authorize(creds)
sh = gc.open_by_key('1tjiYmZQFcJOecTXIdGC9AEBOfZkWlETMKYsC7qRJhVc')
ws = sh.get_worksheet_by_id(0)

rows = ws.get_all_values()

def parse_date_flexible(val):
    val = val.strip()
    if not val:
        return None
    # Check if already 4-digit year format
    val_clean = val.replace('.', '/').replace('-', '/')

    # Try standard YYYY/MM/DD
    for fmt in ('%Y/%m/%d', '%Y/%m/%d %H:%M:%S', '%Y/%m/%d %H:%M'):
        try:
            return datetime.strptime(val_clean[:len(fmt)], fmt)
        except ValueError:
            pass

    # Try parsing parts
    parts = val_clean.split('/')
    if len(parts) == 3:
        try:
            y = int(parts[0])
            m = int(parts[1])
            d = int(parts[2])
            if y < 100:
                y += 2000
            return datetime(y, m, d)
        except ValueError:
            pass
    elif len(parts) == 2:
        # e.g. 3/12 -> assume 2026? Or let's check what year it is associated with or default to 2026
        try:
            m = int(parts[0])
            d = int(parts[1])
            return datetime(2026, m, d)
        except ValueError:
            pass

    return None

a_counts = defaultdict(int)
n_counts = defaultdict(int)

a_total = 0
n_total = 0

for idx, r in enumerate(rows):
    val_a = r[0] if len(r) > 0 else ''
    if val_a.strip():
        dt_a = parse_date_flexible(val_a)
        if dt_a and dt_a >= datetime(2026, 3, 1):
            a_counts[dt_a.strftime('%Y-%m')] += 1
            a_total += 1

    val_n = r[13] if len(r) > 13 else ''
    if val_n.strip():
        dt_n = parse_date_flexible(val_n)
        if dt_n and dt_n >= datetime(2026, 3, 1):
            n_counts[dt_n.strftime('%Y-%m')] += 1
            n_total += 1

print('=== A列 (柔軟パース) ===')
for k in sorted(a_counts.keys()):
    print(f'{k}: {a_counts[k]}件')
print(f'合計: {a_total}件')

print('\n=== N列 (柔軟パース) ===')
for k in sorted(n_counts.keys()):
    print(f'{k}: {n_counts[k]}件')
print(f'合計: {n_total}件')
"
